import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec4 } from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3 } = ctx.THREE;

  const group = new Group();
  const cleanupCallbacks = [];

  // Setup basic geometry based on atlas region source rect (512x320)
  const width = 5.12 * 0.9;
  const height = 3.2 * 0.9;
  const geometry = new PlaneGeometry(width, height);

  // Setup material with basic node-based UV mapping for Atlas Region
  // Region: 0, 0, 512, 320 on assumed 512x512 or mapped normalized UVs.
  // Since we require precise atlas mapping, we map the UV range [0,0] to [1, 320/512 = 0.625].
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false
  });

  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // Stage Backdrop - Engineered Gradient Surface to avoid FLAT_VOID defect (7x6 units at z=-2.5)
  const bgGeom = new PlaneGeometry(7.5, 6.5);
  const bgMat = new MeshBasicNodeMaterial({ depthWrite: false });

  // Custom TSL gradient: vertical gradient from ink (#16161d) to surface (#0b0b10)
  const inkColor = vec3(0.086, 0.086, 0.114); // #16161d
  const surfaceColor = vec3(0.043, 0.043, 0.063); // #0b0b10
  const vUv = uv();
  const gradientMix = vUv.y;
  bgMat.colorNode = vec4(mix(surfaceColor, inkColor, gradientMix), 1.0);

  const bgMesh = new Mesh(bgGeom, bgMat);
  bgMesh.position.set(0, 0, -2.5);
  group.add(bgMesh);

  // Load the sprite accent texture
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      // Atlas source rect mapping: x=0, y=0, w=512, h=320.
      texture.repeat.set(1.0, 320 / 512);
      texture.offset.set(0, 1.0 - (320 / 512));
      material.colorNode = texture;
      material.needsUpdate = true;
    }).catch((err) => {
      console.warn('Failed loading hero image texture', err);
    });
  }

  // Entrance Weighted-Settle motion animation
  mesh.position.y = -0.3;
  mesh.scale.set(0.01, 0.01, 1);
  mesh.rotation.z = -0.05;

  const tl = gsap.timeline();
  tl.to(mesh.scale, {
    x: 1.04,
    y: 1.04,
    duration: 0.7,
    ease: 'power3.out'
  })
  .to(mesh.scale, {
    x: 1.0,
    y: 1.0,
    duration: 0.3,
    ease: 'power4.out'
  }, '-=0.1')
  .to(mesh.position, {
    y: 0,
    duration: 0.9,
    ease: 'power4.out'
  }, 0)
  .to(mesh.rotation, {
    z: 0,
    duration: 0.9,
    ease: 'power4.out'
  }, 0);

  cleanupCallbacks.push(() => {
    tl.kill();
  });

  // Handle billboarding / subtle orientation
  const handleUpdate = () => {
    mesh.lookAt(new Vector3(0, 0, 10));
  };

  // Register cleanup handler
  group.userData = {
    handlers: {
      update: handleUpdate
    },
    cleanup() {
      cleanupCallbacks.forEach((cb) => cb());
      geometry.dispose();
      material.dispose();
      bgGeom.dispose();
      bgMat.dispose();
    }
  };

  return group;
}
